package com.example.mumuautomation;
import android.accessibilityservice.AccessibilityService; import android.accessibilityservice.GestureDescription; import android.graphics.Path; import android.graphics.PixelFormat; import android.os.*; import android.content.*; import android.view.*; import android.widget.*; import java.util.concurrent.atomic.AtomicBoolean;
public class AutomationService extends AccessibilityService {
 WindowManager wm; View panel; WindowManager.LayoutParams params; AtomicBoolean running=new AtomicBoolean(false); Handler handler=new Handler(Looper.getMainLooper()); Thread worker; BroadcastReceiver receiver;
 @Override public void onServiceConnected(){ super.onServiceConnected(); wm=(WindowManager)getSystemService(WINDOW_SERVICE); showPanel(); receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if("SHOW".equals(i.getAction()))showPanel(); else if("HIDE".equals(i.getAction()))hidePanel();}}; if(Build.VERSION.SDK_INT>=33) registerReceiver(receiver,new IntentFilter("com.example.mumuautomation.CONTROL"),Context.RECEIVER_NOT_EXPORTED); else registerReceiver(receiver,new IntentFilter("com.example.mumuautomation.CONTROL")); }
 @Override public void onAccessibilityEvent(android.view.accessibility.AccessibilityEvent e){} @Override public void onInterrupt(){stopMacro();}
 @Override public void onDestroy(){stopMacro();hidePanel();if(receiver!=null)try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}
 void showPanel(){if(panel!=null)return; LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setPadding(12,10,12,10); box.setBackgroundColor(0xee202632); TextView head=new TextView(this);head.setText("MuMu Macro");head.setTextColor(-1);head.setTextSize(16);head.setTypeface(null,1);box.addView(head);
 Button start=new Button(this);start.setText("START");start.setOnClickListener(v->startMacro());box.addView(start); Button stop=new Button(this);stop.setText("STOP");stop.setOnClickListener(v->stopMacro());box.addView(stop); Button close=new Button(this);close.setText("× Hide");close.setOnClickListener(v->hidePanel());box.addView(close);
 params=new WindowManager.LayoutParams(WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.WRAP_CONTENT,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.LEFT;params.x=20;params.y=120; params.width=dp(150); panel=box; try{wm.addView(panel,params);}catch(Exception e){panel=null;Toast.makeText(this,"Overlay permission required",1).show();}}
 void hidePanel(){if(panel!=null){try{wm.removeView(panel);}catch(Exception ignored){}panel=null;}}
 int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
 void startMacro(){if(!running.compareAndSet(false,true))return; worker=new Thread(()->{SharedPreferences p=getSharedPreferences("cfg",0);int loops;try{loops=Integer.parseInt(p.getString("loops","0"));}catch(Exception e){loops=0;} int delay;try{delay=Integer.parseInt(p.getString("delay","900"));}catch(Exception e){delay=900;} int count=0;while(running.get()&&(loops==0||count<loops)){count++;for(int i=0;i<20&&running.get();i++){String s=p.getString("p"+i,"").trim();if(s.isEmpty())continue;String[] xy=s.split(",");if(xy.length!=2)continue;try{tap(Integer.parseInt(xy[0].trim()),Integer.parseInt(xy[1].trim()));Thread.sleep(Math.max(100,delay));}catch(Exception ex){}}}running.set(false);});worker.start();}
 void stopMacro(){running.set(false);}
 void tap(int x,int y){if(Build.VERSION.SDK_INT<24)return;Path path=new Path();path.moveTo(x,y);GestureDescription.Builder b=new GestureDescription.Builder();b.addStroke(new GestureDescription.StrokeDescription(path,0,80));dispatchGesture(b.build(),null,null);}
}
